     `[smoke] ${report.ok ? "PASS" : "FAIL"} on ${process.platform}: ${screens.length} screenshots → ${outDir}`,
   );
   for (const e of errors) console.error(`[smoke] ${e}`);
   return report.ok ? 0 : 1;
 }

