 const textLength = (table: Table, col: number) => {
   const texts = table.rows.map((r) => cellText(r.cells[col] ?? null)).filter(Boolean);
   return texts.length ? texts.reduce((sum, t) => sum + t.length, 0) / texts.length : 0;
